import { Component } from '@angular/core';
import { FormBuilder, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { CompasService } from '../../core/services/compas.service';

@Component({
  selector: 'app-add-compa',
  templateUrl: './add-compa.component.html',
  styleUrls: ['./add-compa.component.scss']
})
export class AddCompaComponent {
  public router: Router;
  form = this.fb.group({
    nombre:      ['', [Validators.required, Validators.maxLength(80)]],
    apellido:    ['', [Validators.required, Validators.maxLength(80)]],
    universidad: ['', Validators.maxLength(150)],
    carrera:     ['', Validators.maxLength(150)],
    ciclo:       ['', Validators.maxLength(50)],
    descripcion: ['', Validators.maxLength(300)]
  });

  submitting = false;
  error      = '';

  constructor(private fb: FormBuilder, private compasService: CompasService, router: Router) {
    this.router = router;
  }

  submit(): void {
    if (this.form.invalid || this.submitting) return;
    this.submitting = true;
    this.error      = '';
    const v = this.form.value;
    this.compasService.create({
      nombre:      v.nombre!,
      apellido:    v.apellido!,
      universidad: v.universidad || undefined,
      carrera:     v.carrera     || undefined,
      ciclo:       v.ciclo       || undefined,
      descripcion: v.descripcion || undefined
    }).subscribe({
      next: (res: any) => this.router.navigate(['/compa', res.id]),
      error: (err: any) => {
        this.error      = err.error?.error ?? 'Error al agregar. Intenta de nuevo.';
        this.submitting = false;
      }
    });
  }
}
<div class="page-wrap">
  <div class="form-card card">
    <div class="form-header">
      <button class="btn-back" (click)="router.navigate(['/'])">← Volver</button>
      <h2>Agregar compañero</h2>
      <p class="form-sub">Completa los datos del compañero que deseas registrar.</p>
    </div>

    <div class="alert alert-error" *ngIf="error">{{ error }}</div>

    <form [formGroup]="form" (ngSubmit)="submit()">
      <div class="form-row">
        <div class="form-group">
          <label>Nombre <span class="required">*</span></label>
          <input type="text" formControlName="nombre" placeholder="Ej: Carlos">
          <span class="error-msg" *ngIf="form.controls['nombre'].invalid && form.controls['nombre'].touched">
            El nombre es obligatorio.
          </span>
        </div>
        <div class="form-group">
          <label>Apellido <span class="required">*</span></label>
          <input type="text" formControlName="apellido" placeholder="Ej: García">
          <span class="error-msg" *ngIf="form.controls['apellido'].invalid && form.controls['apellido'].touched">
            El apellido es obligatorio.
          </span>
        </div>
      </div>

      <div class="form-group">
        <label>Universidad</label>
        <input type="text" formControlName="universidad" placeholder="Ej: Universidad Nacional Mayor de San Marcos">
      </div>

      <div class="form-row">
        <div class="form-group">
          <label>Carrera</label>
          <input type="text" formControlName="carrera" placeholder="Ej: Ingeniería de Sistemas">
        </div>
        <div class="form-group">
          <label>Ciclo</label>
          <input type="text" formControlName="ciclo" placeholder="Ej: 3er ciclo">
        </div>
      </div>

      <div class="form-group">
        <label>Descripción (opcional)</label>
        <textarea formControlName="descripcion" rows="3" placeholder="Describe brevemente a este compañero..."></textarea>
        <span class="char-count">{{ (form.value.descripcion?.length ?? 0) }} / 300</span>
      </div>

      <button type="submit" class="btn btn-primary full" [disabled]="form.invalid || submitting">
        {{ submitting ? 'Guardando...' : 'Agregar compañero' }}
      </button>
    </form>
  </div>
</div>
